import {Trace} from './trace.mjs';
function shell(){const b=new Trace('shell','Shell · files, permissions, and links','Commands change a directory tree. Paths and links identify filesystem objects.',`mkdir lesson\ncd lesson\nprintf 'Z\\n' > z\nchmod 640 z\nln z hard\nln -s z soft\ncat soft\nls -l z hard soft`,{kind:'shell'});b.state.world={kind:'files',cwd:'.',files:[]};b.steps[0].world=structuredClone(b.state.world);b.step('mkdir lesson','Create a directory','Create lesson beneath the current directory.','mkdir creates a directory, while the shell’s current location stays the same.','new directory → filesystem',()=>b.state.world.files.push({name:'lesson/',kind:'directory',content:''}));b.step('cd lesson','Change the current location','Make lesson the shell’s working directory.','cd changes where relative paths are resolved; it creates no file.','current directory → lesson',()=>b.state.world.cwd='lesson');b.step("printf 'Z\\n' > z",'Create file contents','printf produces Z and a newline. The > operator sends them into z, creating or replacing the file.','Redirection writes the file instead of displaying these characters on the terminal.','printf output → z',()=>b.state.world.files.push({name:'z',kind:'file',content:'Z\n',mode:'rw-------',inode:'A'}));b.step('chmod 640 z','Set permissions','6 = read + write for owner, 4 = read for group, 0 = no permissions for others.','chmod changes access metadata, not file contents.','640 → rw-r-----',()=>b.state.world.files.find(f=>f.name==='z').mode='rw-r-----');b.step('ln z hard','Create a hard link','hard names the same file object as z.','These two names share file contents and permissions; this is different from copying a file.','same object A → second name',()=>b.state.world.files.push({name:'hard',kind:'hard link',content:'Z\n',mode:'rw-r-----',inode:'A',target:'z'}));b.step('ln -s z soft','Create a symbolic link','soft stores the relative target path z.','A symlink is a separate object that follows a path. It can become broken if its target path disappears.','target path z → symbolic link',()=>b.state.world.files.push({name:'soft',kind:'symbolic link',content:'z',target:'z'}));b.step('cat soft','Follow and read the link','Follow soft to z and read Z plus newline.','The target file is read without changing its contents.','soft → z → terminal',()=>b.state.output+='Z\n');b.step('ls -l z hard soft','Inspect filesystem metadata','List the file names, permissions, link information, and symbolic target.','The workspace shows these important fields; timestamps, owners, and inode numbers are illustrative rather than captured from your computer.','filesystem metadata → terminal',()=>b.state.output+='z, hard: same object A, rw-r-----\nsoft -> z\n');return b.done();}
function search(){const b=new Trace('search','Shell search · find, grep, and pipes','A pipe passes one command’s standard output into the next command’s standard input.',`find . -type f -name '*.txt'\ngrep -n 'TODO' notes.txt\nprintf 'pear\\napple\\npear\\n' | sort | uniq\nfind . -type f | wc -l`,{kind:'shell'});b.state.world={kind:'files',cwd:'.',files:[{name:'notes.txt',kind:'file',content:'TODO: learn pipes\ndone\n'},{name:'readme.txt',kind:'file',content:'Hello\n'},{name:'main.c',kind:'file',content:'int main(void) { return 0; }'}]};b.steps[0].world=structuredClone(b.state.world);b.step("find . -type f -name '*.txt'",'Select paths by name','Search under the current directory for ordinary files ending in .txt.','The quoted pattern is passed to find without being expanded by the shell first.','tree → matching paths',()=>b.state.output+='./notes.txt\n./readme.txt\n');b.step("grep -n 'TODO' notes.txt",'Select text inside a file','Read notes.txt and print matching lines with line numbers.','find selects paths; grep selects text from file contents. Neither changes the source file.','file text → matching line',()=>b.state.output+='1:TODO: learn pipes\n');b.step("printf 'pear\\napple\\npear\\n' | sort | uniq",'Pass text through a pipeline','printf produces three lines. sort orders them. uniq removes adjacent duplicates.','Each pipe transfers output text, rather than a filename or a memory pointer.','printf → sort → uniq → terminal',()=>b.state.output+='apple\npear\n');b.step('find . -type f | wc -l','Count paths','find emits one path per ordinary file; wc -l counts the newline-delimited paths.','This example uses simple filenames without embedded newlines. That is why counting output lines counts these three paths.','paths → newline count → terminal',()=>b.state.output+='3\n');return b.done();}
function git(){const b=new Trace('git','Git · working tree, index, commit, remote','A saved file, a staged snapshot, a commit, and a pushed commit are different states.',`printf 'v1\\n' > note.txt\ngit add note.txt\nprintf 'v2\\n' > note.txt\ngit commit -m 'Save v1'\ngit status --short\ngit add note.txt\ngit commit -m 'Save v2'\ngit push\ngit log --oneline`,{kind:'git'});b.state.world={kind:'git',work:'absent',index:'absent',commit:'none',remote:'none'};b.steps[0].world=structuredClone(b.state.world);const step=(at,title,what,watch,fn,out='')=>b.step(at,title,what,watch,'working tree → index → commit → remote',()=>{fn(b.state.world);b.state.output+=out;});step("printf 'v1\\n' > note.txt",'Edit the working tree','Write v1 to the file.','There is no staged snapshot or commit yet.',w=>w.work='v1');step('git add note.txt','Stage a snapshot','Copy the current v1 contents into the index.','git add stages the contents now, not future edits.',w=>w.index='v1');step("printf 'v2\\n' > note.txt",'Edit after staging','Replace the working file with v2.','The index still holds v1.',w=>w.work='v2');step("git commit -m 'Save v1'",'Commit the staged version','Create a commit containing v1 from the index.','The unstaged v2 edit is not part of this commit.',w=>w.commit='v1');step('git status --short','Inspect the difference','The working file differs from the committed/staged version.','Status reads state and does not stage or publish anything.',()=>{},' M note.txt\n');step('git add note.txt','Stage the updated contents','Copy v2 into the index.','Now the index matches the working file.',w=>w.index='v2');b.steps.at(-1).line=7-1;step("git commit -m 'Save v2'",'Create the next commit','Commit the staged v2 snapshot.','Commits preserve history, rather than overwriting the previous commit.',w=>w.commit='v2');step('git push','Send commits to the remote','Transfer the local commits to the configured remote in this teaching model.','This simulator does not connect to or change your real Git repository.',w=>w.remote='v2');step('git log --oneline','Inspect history','Read the two commits in reverse chronological order.','The labels are illustrative; real commit IDs depend on their actual contents and metadata.',()=>{},'commit-2 Save v2\ncommit-1 Save v1\n');return b.done();}
function ssh(){const b=new Trace('ssh','SSH · public and private keys','Authentication proves possession of a private key without sharing that private key.',`ssh-keygen -t ed25519\ncat ~/.ssh/id_ed25519.pub\n# Add the public key to your school account\nssh -T git@school.example`,{kind:'shell'});b.step('ssh-keygen -t ed25519','Create a key pair','The command creates a private key and matching public key.','This is a teaching model. It generates no real credentials.','key generator → two different files',()=>b.state.world={kind:'files',cwd:'~/.ssh',files:[{name:'id_ed25519',kind:'private key',content:'kept on your computer'},{name:'id_ed25519.pub',kind:'public key',content:'public identifier for the matching key'}]});b.step('cat ~/.ssh/id_ed25519.pub','Read the public half','Show the public key file, whose name ends in .pub.','The private key contents are never displayed or submitted.','public key file → terminal',()=>b.state.output+='[illustrative public key]\n');b.step('# Add the public key to your school account','Register the public half','The school account records the public key.','This is an explanatory setup action, not an executable shell command.','public key → account’s allowed keys');b.step('ssh -T git@school.example','Authenticate using the pair','The SSH client proves it possesses the matching private key.','The host name is an example. No network connection is attempted by this simulator.','proof → server verifies using registered public key',()=>b.state.output+='[illustration: identity accepted]\n');return b.done();}
function build(){const b=new Trace('build','Compilation · source, object, archive, executable','Compilation and linking are separate stages. A static library groups object files.',`printf 'int add(int a, int b) { return a + b; }\\n' > add.c\nprintf 'int add(int, int); int main(void) { return add(1, 2) != 3; }\\n' > main.c\ncc -Wall -Wextra -Werror -c add.c -o add.o\nar rcs libdemo.a add.o\ncc -Wall -Wextra -Werror main.c libdemo.a -o demo\n./demo\n# make: rebuild only targets whose dependencies changed`,{kind:'build'});b.state.world={kind:'build',phase:'source preparation',items:[]};b.steps[0].world=structuredClone(b.state.world);for(const [i,item,phase,what]of [[1,'add.c','source','Write the implementation of add.'],[2,'main.c','source','Write a caller that declares add and checks its return value.'],[3,'add.o','compile','Compile add.c to an object file. -c stops before final linking.'],[4,'libdemo.a','archive','ar groups add.o into a static archive. An archive is not an executable.'],[5,'demo','link','Compile the caller and link its unresolved add reference with code from the archive.']])b.step(i,'Create '+item,what,'The artifact panel distinguishes editable source from objects, archive, and executable.',phase+' → '+item,()=>{b.state.world.phase=phase;b.state.world.items.push(item);});b.step('./demo','Run the executable','The program calls add(1, 2), gets 3, and returns success.','This program intentionally prints nothing. Exit status and terminal output are different things.','executable → result',()=>{b.state.world.phase='run complete (exit 0)';});b.step('# make: rebuild only targets whose dependencies changed','Understand dependency-driven builds','make decides which targets are out of date from the declared dependencies and file modification times.','Use all/clean/fclean/re targets required by the source PDF. This small archive demonstrates the build mechanism, not the exact required libft.a contents.','dependencies → necessary compile/link commands');return b.done();}
function macro(){const source=`#include <stdio.h>\n#define ABS(x) ((x) < 0 ? -(x) : (x))\nint main(void)\n{\n    int n = -3;\n    int result = ABS(n);\n    printf("%d\\n", result);\n    return (0);\n}`;const b=new Trace('preprocessor','Preprocessor · text expansion before execution','A macro expands source tokens. It does not call a runtime function.',source);b.step('#define ABS(x) ((x) < 0 ? -(x) : (x))','Register a macro','The preprocessor records the replacement tokens for ABS.','This step is before runtime. No int variable or function call frame is created by the macro.','source tokens → macro definition',()=>{b.state.calls=[];b.state.scope='preprocessing';b.state.world={kind:'build',phase:'preprocessing',items:['ABS(x) → ((x) < 0 ? -(x) : (x))']};});b.step('int result = ABS(n);','Expand the use site','Replace ABS(n) with ((n) < 0 ? -(n) : (n)).','Arguments can appear more than once in a macro. This example uses plain n with no side effects. Parentheses protect expression grouping.','ABS(n) tokens → expanded expression',()=>b.state.world.items.push('int result = ((n) < 0 ? -(n) : (n));'));b.step('int n = -3;','Begin runtime in main','After preprocessing and compilation, main initializes n to -3.','Now runtime objects are created. Preprocessing is already finished.','-3 → n',()=>{b.state.scope='main';b.state.calls=['main'];b.state.world.phase='runtime';b.cell('n','n','int',0x1000,-3);});b.step('int result = ABS(n);','Evaluate the expanded expression','The condition n < 0 is true, so -n is 3. Initialize result with 3.','There is no ABS function frame. This is an ordinary expanded expression in main.','expanded expression → result',()=>b.cell('result','result','int',0x1004,3),['n']);return b.finish('printf("%d\\n", result);','3\n');}
function fileRead(){const source=`#include <unistd.h>\n#include <fcntl.h>\nint main(void)\n{\n    char buffer[4];\n    int fd = open("sample.txt", O_RDONLY);\n    if (fd < 0)\n        return (1);\n    int count = (int)read(fd, buffer, 4);\n    if (count < 0)\n    {\n        close(fd);\n        return (1);\n    }\n    write(1, buffer, (unsigned int)count);\n    close(fd);\n    return (0);\n}`;const b=new Trace('file-read','File IO · open, read, write, close','A file descriptor is a handle. read fills a buffer and returns the number of bytes read.',source,{fixtureFiles:{'sample.txt':'Hi\n'}});b.step('char buffer[4];','Create a byte buffer','Reserve four uninitialized char cells.','Reading bytes into a buffer does not automatically create a zero-terminated C string.','buffer capacity → memory',()=>{for(let i=0;i<4;i++)b.cell('b'+i,`buffer[${i}]`,'char',0x1000+i,undefined);b.state.world={kind:'files',cwd:'.',files:[{name:'sample.txt',kind:'file',content:'Hi\n'}]};});b.step('int fd = open("sample.txt", O_RDONLY);','Open the file','Open sample.txt for reading and store the returned handle.','The handle 3 is illustrative. A descriptor is an integer identifying an open file, not a memory address.','path → open file handle',()=>{b.cell('fd','fd','file descriptor',0x2000,3);b.state.world.handles=[{fd:3,status:'open',file:'sample.txt'}];});b.step('if (fd < 0)','Check open success','The modeled descriptor is nonnegative, so continue.','A failed open must be handled before read.','nonnegative → continue',()=>{},['fd']);b.step('int count = (int)read(fd, buffer, 4);','Read actual bytes','The file supplies three bytes: H, i, and newline. count receives 3.','The fourth cell remains uninitialized. read can return fewer bytes than requested; only the returned count is valid data.','file bytes → buffer; 3 → count',()=>{b.set('b0','H');b.set('b1','i');b.set('b2','\\n');b.cell('count','count','int',0x2004,3);},['fd'],['b0','b1','b2']);b.step('if (count < 0)','Check read success','count is 3, so the error branch is skipped.','A zero count would mean end of file in this ordinary regular-file read.','nonnegative → write',()=>{},['count']);b.step('write(1, buffer, (unsigned int)count);','Write only the bytes read','Write exactly three valid bytes to standard output.','The uninitialized fourth cell is never read. This small regular-file example demonstrates the byte-count mechanism; a complete IO program must handle errors and partial writes.','buffer[0..2] → stdout',()=>b.state.output+='Hi\n',['count','b0','b1','b2']);b.step('close(fd);','Close the descriptor','Release the open file handle.','Closing the file does not destroy the local buffer or change its contents.','file handle → closed',()=>b.state.world.handles[0].status='closed',['fd']);return b.finish('return (0);','');}
function tail(){const source=`#include <stdio.h>\n#include <string.h>\nint main(void)\n{\n    char buffer[] = "ABCDE";\n    int size = (int)strlen(buffer);\n    int wanted = 2;\n    int start = size > wanted ? size - wanted : 0;\n    printf("%s\\n", buffer + start);\n    return (0);\n}`;const b=new Trace('tail-bytes','Tail -c · the last N bytes','Select the final bytes with a bounded starting offset. This example uses an already-read buffer.',source);b.step('char buffer[] = "ABCDE";','Create five bytes plus zero','Initialize the illustrative file-content buffer.','The source exercise’s -c option refers to bytes, not lines.','bytes → buffer',()=>b.chars('b','ABCDE',0x1000,'buffer'));b.step('int size = (int)strlen(buffer);','Measure the sample data','This sample has five text bytes before zero.','Real binary file byte counts come from read, not strlen. This miniature text buffer isolates the tail-selection rule.','5 → size',()=>b.cell('size','size','int',0x2000,5));b.step('int wanted = 2;','Choose the byte count','Ask for the last two bytes.','The count is independent of line breaks.','2 → wanted',()=>b.cell('wanted','wanted','int',0x2004,2));b.step('int start = size > wanted ? size - wanted : 0;','Find a safe starting offset','5 > 2, so start = 5 - 2 = 3.','When the requested count exceeds the available size, start stays zero.','size - wanted → start',()=>b.cell('start','start','int',0x2008,3),['size','wanted']);return b.finish('printf("%s\\n", buffer + start);','DE\n','Calculate &buffer[3] and print from that position to the terminator.');}
function hex(){const b=new Trace('hexdump','Hexdump · bytes as hex digits','Formatting a byte changes how it is displayed, not the byte stored in memory.',`#include <stdio.h>\nint main(void)\n{\n    unsigned char bytes[2] = {65, 10};\n    int i = 0;\n    while (i < 2)\n    {\n        printf("%02x ", (unsigned int)bytes[i]);\n        i++;\n    }\n    putchar('\n');\n    return (0);\n}`.replace("putchar('\n');","putchar('\\n');"));b.step('unsigned char bytes[2] = {65, 10};','Create two bytes','Store 65 and 10 as unsigned bytes.','Their hex representations are 41 and 0a. This concept example is not the complete hexdump column/offset formatting required by the assignment.','byte values → storage',()=>{b.cell('b0','bytes[0]','unsigned char',0x1000,65);b.cell('b1','bytes[1]','unsigned char',0x1001,10);});b.step('int i = 0;','Start the index','Set i to zero.','The example visits exactly two initialized bytes.','0 → i',()=>b.cell('i','i','int',0x2000,0));for(let i=0;i<2;i++){b.step('while (i < 2)','Check the byte count',`${i} < 2 is true.`,'No bytes outside the array are read.','true → output',()=>{},['i']);b.step('printf("%02x ", (unsigned int)bytes[i]);','Format the byte as hex',`Format ${i?10:65} as ${i?'0a':'41'}.`,'The cast supplies the unsigned int expected by %x. The original byte remains unchanged.','byte → two hex digits → terminal',()=>b.state.output+=i?'0a ':'41 ',['b'+i]);b.step('i++;','Move to the next byte',`Set i to ${i+1}.`,'Only the index changes.','i + 1 → i',()=>b.set('i',i+1));}b.step('while (i < 2)','End the byte loop','2 < 2 is false.','Both bytes were printed once.','false → stop',()=>{},['i']);return b.finish("putchar('\\n');",'\n');}
export function buildSystemSimulations(){return [shell(),search(),git(),ssh(),build(),macro(),fileRead(),tail(),hex()];}
